document.addEventListener('DOMContentLoaded', () => {

    const ui = {
        totalAnomalies: document.getElementById('total-anomalies'),
        maxScore: document.getElementById('max-score'),
        avgLead: document.getElementById('avg-lead'),
        lastUpdated: document.getElementById('last-updated'),
        list: document.getElementById('anomalies-list')
    };

    // Load data from JSON (generated by Python script)
    async function loadData() {
        try {
            // Add cache buster to prevent stale PWA data
            const res = await fetch(`data/anomalies.json?t=${new Date().getTime()}`);
            if (!res.ok) throw new Error('Data not found');
            const data = await res.json();

            renderDashboard(data);
        } catch (error) {
            console.error('Failed to load data:', error);
            ui.list.innerHTML = `
                <div class="loader-container">
                    <p style="color: var(--accent-red)">⚠️ Connection Error</p>
                    <p style="font-size: 0.75rem; margin-top: 5px;">Waiting for pipeline sync...</p>
                </div>
            `;
        }
    }

    function renderDashboard(anomalies) {
        // Update stats
        ui.totalAnomalies.textContent = anomalies.length;

        if (anomalies.length > 0) {
            const max = Math.max(...anomalies.map(a => a.score));
            ui.maxScore.innerHTML = `${Math.round(max)}<span class="muted">/100</span>`;

            const totalLead = anomalies.reduce((acc, a) => acc + (a.lead_time_days || 0), 0);
            const avg = Math.round(totalLead / anomalies.length);
            ui.avgLead.innerHTML = `+${avg || 0}<span class="muted">d</span>`;

            // Last updated from latest anomaly
            const latest = anomalies[0].detection_date;
            if (latest) {
                const dt = new Date(latest);
                ui.lastUpdated.textContent = dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            }

            // Render list
            ui.list.innerHTML = '';
            anomalies.forEach((anomaly, index) => {
                const el = createAnomalyCard(anomaly, index * 0.1);
                ui.list.appendChild(el);
            });
        } else {
            ui.list.innerHTML = `
                <div class="loader-container" style="opacity: 0.7">
                    <p>No active anomalies on radar.</p>
                </div>
            `;
        }
    }

    function createAnomalyCard(anomaly, delay) {
        const div = document.createElement('div');

        // Determine threat level class based on score
        let levelClass = 'medium';
        if (anomaly.score >= 80) levelClass = 'critical';
        else if (anomaly.score >= 60) levelClass = 'high';

        div.className = `anomaly-item ${levelClass}`;
        div.style.animationDelay = `${delay}s`;

        // Format date string
        const dateObj = new Date(anomaly.detection_date);
        const dateStr = `${dateObj.getDate()}/${dateObj.getMonth() + 1} - ${dateObj.getHours()}:${String(dateObj.getMinutes()).padStart(2, '0')}`;

        div.innerHTML = `
            <div class="item-header">
                <div class="player-info">
                    <h4>${anomaly.player_name}</h4>
                    <span class="item-region">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><path d="M2 12h20"></path><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>
                        ${anomaly.region || 'Global Market'}
                    </span>
                </div>
                <div class="score-badge">${Math.round(anomaly.score)}</div>
            </div>
            
            <div class="item-metrics">
                <div class="metric">
                    <span>Lead Time</span>
                    <strong>+${anomaly.lead_time_days || 0} Days</strong>
                </div>
                <div class="metric">
                    <span>Detection</span>
                    <strong style="color: var(--text-primary)">${dateStr}</strong>
                </div>
            </div>
            
            <div class="item-context">
                ${anomaly.raw_content || 'Raw anomaly detection signal isolated from regional noise.'}
            </div>
        `;

        return div;
    }

    // Init
    loadData();

    // Auto refresh every 5 mins if kept open
    setInterval(loadData, 300000);
});
